import{_ as s,C as i,o as t,c as n,a2 as a,b as d,w as r,a as l,E as c,a3 as h}from"./chunks/framework.Dd_iHz3e.js";const v=JSON.parse('{"title":"14.5 Databases & Storage: SQL, NoSQL & Polyglot Persistence","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.5-databases-and-storage.md","filePath":"system-design/14.5-databases-and-storage.md"}'),g={name:"system-design/14.5-databases-and-storage.md"};function p(u,e,m,S,y,b){const o=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="_14-5-databases-storage-sql-nosql-polyglot-persistence" tabindex="-1">14.5 Databases &amp; Storage: SQL, NoSQL &amp; Polyglot Persistence <a class="header-anchor" href="#_14-5-databases-storage-sql-nosql-polyglot-persistence" aria-label="Permalink to &quot;14.5 Databases &amp; Storage: SQL, NoSQL &amp; Polyglot Persistence&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Databases store, query, and preserve application data, balancing structural guarantees (ACID transactions), query flexibility (document vs relational), horizontal scalability, and latency.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Primary Operational Store</strong>: MongoDB with Mongoose ODM <code>^8.23.0</code> ([models/User.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/models/User.js), [models/SafetyLog.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/models/SafetyLog.js), [models/Member.js](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/models/Member.js)).</li><li><strong>Object Storage (Media)</strong>: S3-compatible cloud object store for 1080p culinary reel video MP4s and recipe photography.</li><li><strong>Client Cache</strong>: Browser <code>localStorage</code> for offline session and theme preferences.</li></ul><hr><h2 id="_3-database-cluster-sharding-architecture" tabindex="-1">3. Database Cluster &amp; Sharding Architecture <a class="header-anchor" href="#_3-database-cluster-sharding-architecture" aria-label="Permalink to &quot;3. Database Cluster &amp; Sharding Architecture&quot;">​</a></h2>',8)),(t(),d(h,null,{default:r(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20AppServers%5B%22Express%20Backend%20Instances%22%5D%20--%3E%20MongosRouter%5B%22mongos%20Query%20Router%22%5D%0A%20%20%20%20MongosRouter%20--%3E%20ConfigServer%5B%22Config%20Server%20Replica%20Set%22%5D%0A%20%20%20%20MongosRouter%20--%3E%20Shard1%5B%22Shard%201%3A%20User%20%26%20Member%20Data%20(Hashed%20key%3A%20_id)%22%5D%0A%20%20%20%20MongosRouter%20--%3E%20Shard2%5B%22Shard%202%3A%20SafetyLog%20Partition%20(Ranged%3A%20createdAt)%22%5D%0A%20%20%20%20MongosRouter%20--%3E%20Shard3%5B%22Shard%203%3A%20Social%20%26%20Reel%20Activity%22%5D%0A%0A%20%20%20%20Shard1%20--%3E%20Shard1Replica%5B%22Shard%201%20Secondary%20Replicas%22%5D%0A%20%20%20%20Shard2%20--%3E%20Shard2Replica%5B%22Shard%202%20Secondary%20Replicas%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_4-comprehensive-storage-paradigm-comparison" tabindex="-1">4. Comprehensive Storage Paradigm Comparison <a class="header-anchor" href="#_4-comprehensive-storage-paradigm-comparison" aria-label="Permalink to &quot;4. Comprehensive Storage Paradigm Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Storage Category</th><th>Technology</th><th>Data Structure</th><th>ACID Guarantee</th><th>Scalability</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Document NoSQL (Chosen)</strong></td><td>MongoDB / Mongoose</td><td>BSON Documents</td><td>Document-level ACID</td><td>Native Horizontal Sharding</td><td>Optimal for polymorphic recipes &amp; logs</td></tr><tr><td><strong>Relational (RDBMS)</strong></td><td>PostgreSQL / MySQL</td><td>Strict Tables &amp; Rows</td><td>Strict Multi-Table ACID</td><td>Vertical / Citus Sharding</td><td>Best for future creator royalty ledgers</td></tr><tr><td><strong>Key-Value Cache</strong></td><td>Redis / Memcached</td><td>In-Memory Strings/Hashes</td><td>Atomic operations</td><td>Redis Cluster</td><td>Essential for sub-millisecond session cache</td></tr><tr><td><strong>Time-Series Engine</strong></td><td>InfluxDB / TimescaleDB</td><td>Timestamped Metrics</td><td>Eventual</td><td>High-throughput Partitioning</td><td>Ideal for IoT sensor temperature curves</td></tr><tr><td><strong>Vector Database</strong></td><td>Pinecone / pgvector</td><td>Float32 Embedding Arrays</td><td>Eventual</td><td>Horizontal Index Sharding</td><td>Ideal for semantic recipe similarity search</td></tr><tr><td><strong>Blob / Object Store</strong></td><td>AWS S3 / Cloudflare R2</td><td>Binary Blobs (MP4, WebP)</td><td>Read-after-write</td><td>Unlimited Cloud Scale</td><td>Mandatory for recipe videos &amp; photos</td></tr></tbody></table><hr><h2 id="_5-cap-pacelc-theorem-position" tabindex="-1">5. CAP &amp; PACELC Theorem Position <a class="header-anchor" href="#_5-cap-pacelc-theorem-position" aria-label="Permalink to &quot;5. CAP &amp; PACELC Theorem Position&quot;">​</a></h2><ul><li><strong>CAP Theorem</strong>: MongoDB is traditionally a <strong>CP System</strong> (Consistency &amp; Partition Tolerance). In a network partition, the majority partition elects a primary while the minority rejects writes, guaranteeing consistent reads and preventing split-brain safety logs.</li><li><strong>PACELC Theorem</strong>: In Normal operation (Else), MongoDB trades off strict write latency for tunable consistency (<code>w: &quot;majority&quot;, j: true</code> vs <code>w: 1</code>).</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Unindexed queries on <code>Member.preferences</code> or <code>SafetyLog.hazard</code> trigger full collection scans, spiking CPU to 100%.</li><li><strong>At 100x</strong>: Single MongoDB primary disk I/O saturates from continuous append-only safety log writes.</li><li><strong>At 1,000x</strong>: Shard key hotspotting: if <code>SafetyLog</code> is sharded by timestamp, all write traffic hammers a single active shard.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><ol><li><strong>Sharding Strategy</strong>: Shard the <code>SafetyLog</code> collection using a <strong>Compound Hashed Shard Key</strong> (<code>{ deviceId: &quot;hashed&quot;, createdAt: 1 }</code>), distributing write traffic evenly across all cluster shards.</li><li><strong>TTL Index for Ephemeral Logs</strong>: Add a TTL index to auto-delete low-severity safety logs older than 90 days:<div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">safetySchema.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ createdAt: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, { expireAfterSeconds: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7776000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div></li><li><strong>Polyglot Evolution</strong>: Retain MongoDB for recipes and telemetry, but introduce <strong>PostgreSQL</strong> for creator earnings and payouts.</li></ol><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;We chose MongoDB because culinary recipes and kitchen sensor events are inherently unstructured documents. A recipe has variable ingredient lists and prep steps, while safety logs are append-heavy telemetry entries. MongoDB gives us document-level ACID guarantees, native horizontal sharding, and effortless JSON mapping to our Node backend. If our creator monetization logic grows to require complex multi-table financial ledgers, I would transition financial balances to PostgreSQL in a polyglot architecture.&quot;</p>',15))])}const k=s(g,[["render",p]]);export{v as __pageData,k as default};
